    Register-ScheduledTask -TaskName "OracleSystems_UltraHD_4D5D_VaultFactory" -Action $actQ -Trigger $trgQ -Settings $setQ -Description "Overnight resumable 1080p/30fps 4D Tesseract + 5D Mobius full-length video upgrader" -Force | Out-Null
    Write-Host "[TASK PASS] Registered OracleSystems_UltraHD_4D5D_VaultFactory (upgrades 2 Full + 3 Shorts every night until all 104/104 are Ultra-HD 4D/5D!)" -ForegroundColor Green
} catch {
    Write-Host "[TASK NOTE] $($_.Exception.Message)" -ForegroundColor Yellow
}

