if (Test-Path "$ProjectDir\Modules\weekly_full_scheduler.py") { python "$ProjectDir\Modules\weekly_full_scheduler.py" }
if (Test-Path "$ProjectDir\optimize_ram_and_boot.ps1") { & "$ProjectDir\optimize_ram_and_boot.ps1" -TrimNow }

$SafeFiles = @(
    "Upgrade_UltraHD_4D5D_Everything.ps1","static/oracle_webgl_store.html",
    "Modules/upgrade_store_4d5d_webgl.py","Modules/upgrade_thumbnails_4k_4d5d.py",
    "Modules/render_real_full_reading.py","Modules/render_cinema_short.py",
    "Modules/vault_full_length_queue.py","Modules/sync_youtube_cinema.py"
)
foreach ($sf in $SafeFiles) { if (Test-Path "$ProjectDir\$sf") { git add -- $sf } }
if (git diff --cached --name-only) {
